2	 * 传感器数据融合模块
3	 * 负责加速度与角速度数据融合、校准和滤波
4	 */
5	
6	import { DEFAULT_THRESHOLDS } from './constants'
7	
8	class SensorFusion {
9	  constructor() {
10	    // 零偏校准值
11	    this.accelOffset = { x: 0, y: 0, z: 0 }
12	    this.gyroOffset = { x: 0, y: 0, z: 0 }
13	
14	    // 滤波器状态
15	    this.filteredAccel = { x: 0, y: 0, z: 0 }
16	    this.filteredGyro = { x: 0, y: 0, z: 0 }
17	
18	    // 滤波系数 (0-1, 越小越平滑)
19	    this.filterCoeff = 0.3
20	
21	    // 是否已校准
22	    this.isCalibrated = false
23	  }
24	
25	  /**
26	   * 零偏校准
27	   * 在静止状态下采集数据，计算零偏
28	   */
29	  calibrate(accelSamples, gyroSamples) {
30	    if (accelSamples.length === 0 || gyroSamples.length === 0) {
31	      console.error('校准数据不足')
32	      return false
33	    }
34	
35	    // 计算加速度零偏
36	    const accelSum = accelSamples.reduce((sum, s) => ({
37	      x: sum.x + s.x,
38	      y: sum.y + s.y,
39	      z: sum.z + s.z
40	    }), { x: 0, y: 0, z: 0 })
41	
42	    this.accelOffset = {
43	      x: accelSum.x / accelSamples.length,
44	      y: accelSum.y / accelSamples.length,
45	      z: (accelSum.z / accelSamples.length) - 9.8 // 减去重力加速度
46	    }
47	
48	    // 计算角速度零偏
49	    const gyroSum = gyroSamples.reduce((sum, s) => ({
50	      x: sum.x + s.x,
51	      y: sum.y + s.y,
52	      z: sum.z + s.z
53	    }), { x: 0, y: 0, z: 0 })
54	
55	    this.gyroOffset = {
56	      x: gyroSum.x / gyroSamples.length,
57	      y: gyroSum.y / gyroSamples.length,
58	      z: gyroSum.z / gyroSamples.length
59	    }
60	
61	    this.isCalibrated = true
62	    console.log('传感器校准完成')
63	    return true
64	  }
65	
66	  /**
67	   * 校准原始数据
68	   */
69	  calibrateData(accel, gyro) {
70	    return {
71	      accel: {
72	        x: accel.x - this.accelOffset.x,
73	        y: accel.y - this.accelOffset.y,
74	        z: accel.z - this.accelOffset.z
75	      },
76	      gyro: {
77	        x: gyro.x - this.gyroOffset.x,
78	        y: gyro.y - this.gyroOffset.y,
79	        z: gyro.z - this.gyroOffset.z
80	      }
81	    }
82	  }
83	
84	  /**
85	   * 低通滤波器
86	   * 用于平滑数据，减少噪声
87	   */
88	  lowPassFilter(current, previous, alpha) {
89	    return {
90	      x: alpha * current.x + (1 - alpha) * previous.x,
91	      y: alpha * current.y + (1 - alpha) * previous.y,
92	      z: alpha * current.z + (1 - alpha) * previous.z
93	    }
94	  }
95	
96	  /**
97	   * 应用滤波
98	   */
99	  applyFilter(accel, gyro) {
100	    this.filteredAccel = this.lowPassFilter(accel, this.filteredAccel, this.filterCoeff)
101	    this.filteredGyro = this.lowPassFilter(gyro, this.filteredGyro, this.filterCoeff)
102	
103	    return {
104	      accel: { ...this.filteredAccel },
105	      gyro: { ...this.filteredGyro }
106	    }
107	  }
108	
109	  /**
110	   * 融合处理
111	   * 完整的数据处理流水线：校准 → 滤波
112	   */
113	  fuse(rawAccel, rawGyro) {
114	    // 1. 校准
115	    const calibrated = this.calibrateData(rawAccel, rawGyro)
116	
117	    // 2. 滤波
118	    const filtered = this.applyFilter(calibrated.accel, calibrated.gyro)
119	
120	    return {
121	      accel: filtered.accel,
122	      gyro: filtered.gyro,
123	      magnitude: {
124	        accel: this.getMagnitude(filtered.accel),
125	        gyro: this.getMagnitude(filtered.gyro)
126	      }
127	    }
128	  }
129	
130	  /**
131	   * 计算向量幅值
132	   */
133	  getMagnitude(vector) {
134	    return Math.sqrt(vector.x * vector.x + vector.y * vector.y + vector.z * vector.z)
135	  }
