/**
 * 传感器数据模拟测试
 * 用于验证挥拍检测和击球分类算法
 */

// 模拟传感器数据
function generateAccelData(magnitude, direction = 'up') {
  const noise = () => (Math.random() - 0.5) * 2
  switch (direction) {
    case 'up':
      return { x: noise(), y: -magnitude + noise(), z: noise() }
    case 'down':
      return { x: noise(), y: magnitude + noise(), z: noise() }
    case 'horizontal':
      return { x: magnitude + noise(), y: noise(), z: noise() }
    default:
      return { x: noise(), y: noise(), z: magnitude + noise() }
  }
}

function generateGyroData(magnitude) {
  const noise = () => (Math.random() - 0.5) * 10
  return { x: magnitude + noise(), y: noise(), z: noise() }
}

// 模拟挥拍数据序列
function simulateSmash() {
  const data = []
  const duration = 150 // 150ms 挥拍

  // 准备阶段 (低加速度)
  for (let i = 0; i < 5; i++) {
    data.push({
      accel: generateAccelData(2),
      gyro: generateGyroData(20),
      timestamp: Date.now() + i * 20
    })
  }

  // 加速阶段 (高加速度，向下)
  for (let i = 0; i < 5; i++) {
    data.push({
      accel: generateAccelData(25 + i * 5, 'down'),
      gyro: generateGyroData(350 + i * 30),
      timestamp: Date.now() + 100 + i * 20
    })
  }

  // 减速阶段
  for (let i = 0; i < 5; i++) {
    data.push({
      accel: generateAccelData(15 - i * 3, 'down'),
      gyro: generateGyroData(200 - i * 40),
      timestamp: Date.now() + 200 + i * 20
    })
  }

  return data
}

function simulateHighClear() {
  const data = []

  // 向上挥拍
  for (let i = 0; i < 5; i++) {
    data.push({
      accel: generateAccelData(12 + i * 2, 'up'),
      gyro: generateGyroData(180 + i * 20),
      timestamp: Date.now() + i * 40
    })
  }

  // 峰值
  for (let i = 0; i < 3; i++) {
    data.push({
      accel: generateAccelData(18, 'up'),
      gyro: generateGyroData(250),
      timestamp: Date.now() + 200 + i * 40
    })
  }

  // 减速
  for (let i = 0; i < 4; i++) {
    data.push({
      accel: generateAccelData(15 - i * 3, 'up'),
      gyro: generateGyroData(200 - i * 30),
      timestamp: Date.now() + 320 + i * 40
    })
  }

  return data
}

